CREATE DATABASE IF NOT EXISTS student_placement_portal CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE student_placement_portal;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS interviews,notifications,feedback,applications,placements,jobs,certifications,skills,education,students,companies,admins,users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,role ENUM('student','company','admin') NOT NULL,name VARCHAR(150) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,username VARCHAR(100) UNIQUE,password_hash VARCHAR(255) NOT NULL,status ENUM('active','inactive','pending') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE students(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,full_name VARCHAR(150) NOT NULL,mobile VARCHAR(20),dob DATE NULL,gender VARCHAR(30),address TEXT,college VARCHAR(200),course VARCHAR(120),department VARCHAR(120),year VARCHAR(30),semester VARCHAR(30),roll_number VARCHAR(80),prn VARCHAR(100),cgpa DECIMAL(4,2),skills TEXT,certifications TEXT,profile_photo VARCHAR(255),resume VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE companies(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,company_name VARCHAR(180) NOT NULL,company_email VARCHAR(150) NOT NULL,contact_number VARCHAR(30),website VARCHAR(255),industry VARCHAR(120),address TEXT,hr_name VARCHAR(120),hr_email VARCHAR(150),description TEXT,logo VARCHAR(255),approval_status ENUM('pending','approved','rejected') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE admins(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE education(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,qualification VARCHAR(150),institute VARCHAR(200),passing_year YEAR NULL,percentage DECIMAL(5,2),FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE skills(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,skill_name VARCHAR(120),proficiency VARCHAR(50),FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE certifications(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,certificate_name VARCHAR(200),issuer VARCHAR(150),issue_date DATE NULL,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE jobs(id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,job_title VARCHAR(180) NOT NULL,description TEXT,responsibilities TEXT,required_skills TEXT,qualification VARCHAR(200),department VARCHAR(120),min_cgpa DECIMAL(4,2) DEFAULT 0,passing_year VARCHAR(20),package_lpa DECIMAL(8,2),location VARCHAR(150),job_type VARCHAR(50),openings INT DEFAULT 1,application_deadline DATE,selection_process TEXT,status ENUM('pending','approved','rejected','inactive') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE applications(id INT AUTO_INCREMENT PRIMARY KEY,job_id INT NOT NULL,student_id INT NOT NULL,status ENUM('applied','under_review','shortlisted','interview_scheduled','selected','rejected') DEFAULT 'applied',applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY unique_application(job_id,student_id),FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE interviews(id INT AUTO_INCREMENT PRIMARY KEY,application_id INT NOT NULL,interview_date DATETIME,mode VARCHAR(50),location_or_link VARCHAR(255),notes TEXT,status ENUM('scheduled','completed','cancelled') DEFAULT 'scheduled',FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE);
CREATE TABLE placements(id INT AUTO_INCREMENT PRIMARY KEY,application_id INT NOT NULL UNIQUE,joining_date DATE NULL,offer_package DECIMAL(8,2),offer_status VARCHAR(50) DEFAULT 'selected',FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE);
CREATE TABLE notifications(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(180) NOT NULL,message TEXT NOT NULL,is_read TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE feedback(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,student_name VARCHAR(150),email VARCHAR(150),rating TINYINT NOT NULL,message TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
